script:
(function () {
  'use strict';
  // 401(k) spend it or save it: what happens to a 401(k) balance when you leave a job.
  //   Cash out: the plan withholds 20% of an eligible rollover distribution paid to you. The whole
  //     balance is taxable: federal tax = tax(other taxable income + balance) - tax(other taxable
  //     income) with 2026 brackets and the standard deduction (or balance x your rate), plus 10%
  //     additional tax if under 59 1/2 and not separated from service in or after the year you turn
  //     55 (50 for qualified public safety employees in a governmental plan), plus state tax at a
  //     flat rate. Federal settle-up at filing = federal tax + 10% tax - 20% withheld.
  //   Direct rollover / leave in plan: no tax now; value at retirement =
  //     balance x ((1 + return) x (1 - yearly fee))^(years to retirement); after tax = value x
  //     (1 - retirement tax rate).
  //   60-day indirect rollover: check = 80%; to roll over everything you add the 20% withheld from
  //     other money within 60 days. Depositing only the check leaves the 20% taxable (plus the 10%
  //     tax if it applies); the 20% withheld is credited when you file.
  // CHECKS (Node, scratch tests, each against a hand calculation):
  //   Defaults ($50,000, age 35, left at 35, single, $60,000 other income, 5% state): taxable income
  //   $43,900 -> $93,900, bracket tax $5,020 -> $15,370, so federal tax on the cash-out = $10,350.00;
  //   10% tax $5,000; state $2,500; kept $32,150.00; withheld $10,000, still owed at filing $5,350.00.
  //   Rollover: 50,000 x (1.06 x 0.995)^30 = $247,080.45; after 20% tax $197,664.36.
  //   Trap: $10,000 to make up; depositing only the check -> $10,000 taxable = $1,550 federal
  //   ($6,500 at 12% + $3,500 at 22%) + $500 state + $1,000 additional = $3,050.00.
  //   Own 22% rate -> $11,000. No other income, $10,000 -> $0 federal (standard deduction), refund
  //   $1,000 of the $2,000 withheld after the $1,000 additional tax. Left at 55 (age 56) -> no 10% tax;
  //   left at 54 -> 10% tax; public safety employee who left at 50 -> none; age 59.5 -> none.
  //   Pub. 575 example: $10,000 distribution -> $2,000 withheld, $8,000 check.
  // ---- 2026 FEDERAL CONSTANTS AND RULES (tax year 2026) ------------------------------------------
  // Brackets and standard deductions: IRS Rev. Proc. 2025-32 (as amended by P.L. 119-21), sections
  //   4.01 and 4.03 - same constants as income-tax-calculator.
  // 20% mandatory withholding on eligible rollover distributions paid to you; no withholding on a
  //   direct rollover; 60-day rollover; the withheld part counts as distributed: IRS Pub. 575 (2025),
  //   "Withholding requirements", "Payment-to-you option", Table 1; IRC 3405(c).
  // 10% additional tax before 59 1/2 and the separation-from-service exception (in or after the year
  //   you reach 55; the earlier of 50 or 25 years of service for qualified public safety employees in
  //   a governmental plan): IRC 72(t)(2)(A)(v), 72(t)(10); IRS Topic 558; Pub. 575 (2025).
  var TAX_YEAR = 2026;
  var BRACKETS = { // upper limit of each band; rates 10, 12, 22, 24, 32, 35, 37%
    single: [12400, 50400, 105700, 201775, 256225, 640600],
    mfj:    [24800, 100800, 211400, 403550, 512450, 768700],
    mfs:    [12400, 50400, 105700, 201775, 256225, 384350],
    hoh:    [17700, 67450, 105700, 201750, 256200, 640600]
  };
  var RATES = [0.10, 0.12, 0.22, 0.24, 0.32, 0.35, 0.37];
  var STANDARD_DEDUCTION = { single: 16100, mfj: 32200, mfs: 16100, hoh: 24150 };
  var WITHHOLDING_RATE = 0.20, ADDITIONAL_TAX = 0.10, EARLY_AGE = 59.5;
  var SEPARATION_AGE = 55, SEPARATION_AGE_SAFETY = 50;
  // ------------------------------------------------------------------------------------------------

  function ordinaryTax(income, status) {
    var limits = BRACKETS[status], tax = 0, lower = 0;
    for (var i = 0; i < RATES.length; i++) {
      var upper = i < limits.length ? limits[i] : Infinity;
      if (income > lower) tax += (Math.min(income, upper) - lower) * RATES[i];
      lower = upper;
    }
    return tax;
  }
  // Federal income tax caused by adding `amount` of ordinary income.
  function federalTaxOn(amount, t) {
    if (amount <= 0) return 0;
    if (t.mode === 'rate') return amount * t.rate;
    var sd = STANDARD_DEDUCTION[t.status];
    return ordinaryTax(Math.max(0, t.income + amount - sd), t.status) - ordinaryTax(Math.max(0, t.income - sd), t.status);
  }
  function owesAdditionalTax(age, sepAge, safety) {
    if (age >= EARLY_AGE) return false;
    return sepAge < (safety ? SEPARATION_AGE_SAFETY : SEPARATION_AGE);
  }
  function growth(rate, fee) { return (1 + rate) * (1 - fee); }

  // p: { balance, age, retire, sepAge, safety, rate, planFee, iraFee, state, retireTax, tax: {mode, rate, status, income} }
  function compute(p) {
    var b = p.balance, early = owesAdditionalTax(p.age, p.sepAge, p.safety);
    var withheld = b * WITHHOLDING_RATE, fed = federalTaxOn(b, p.tax);
    var addl = early ? b * ADDITIONAL_TAX : 0, state = b * p.state;
    var totalTax = fed + addl + state;
    var years = Math.max(0, p.retire - p.age);
    var ira = b * Math.pow(growth(p.rate, p.iraFee), years), plan = b * Math.pow(growth(p.rate, p.planFee), years);
    var short = b * WITHHOLDING_RATE;
    var trapTax = federalTaxOn(short, p.tax) + short * p.state + (early ? short * ADDITIONAL_TAX : 0);
    var rows = [];
    for (var k = 0; k <= Math.floor(years + 1e-9); k++) {
      rows.push({ age: p.age + k, ira: b * Math.pow(growth(p.rate, p.iraFee), k), plan: b * Math.pow(growth(p.rate, p.planFee), k) });
    }
    if (years - Math.floor(years + 1e-9) > 1e-9) rows.push({ age: p.retire, ira: ira, plan: plan });
    return { early: early, withheld: withheld, check: b - withheld, fed: fed, addl: addl, state: state,
             totalTax: totalTax, net: b - totalTax, settle: fed + addl - withheld, years: years,
             ira: ira, plan: plan, iraAfter: ira * (1 - p.retireTax), planAfter: plan * (1 - p.retireTax),
             trapMakeUp: short, trapTax: trapTax, rows: rows };
  }

  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  function money(x) { return moneyFmt.format(Math.abs(x) < 0.005 ? 0 : x); }
  function el(id) { return document.getElementById(id); }
  function num(id) {
    var raw = el(id).value;
    if (raw === '' || raw === null || raw === undefined) return NaN;
    var v = parseFloat(raw);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { el(id).textContent = text; }
  function fillRows(id, rows) {
    var body = el(id);
    body.textContent = '';
    rows.forEach(function (cells) {
      var tr = document.createElement('tr');
      cells.forEach(function (v) { var td = document.createElement('td'); td.textContent = v; tr.appendChild(td); });
      body.appendChild(tr);
    });
  }
  function ageText(a) { return Math.abs(a - Math.round(a)) < 1e-9 ? String(Math.round(a)) : a.toFixed(1); }
  var OUTPUTS = ['ksNet', 'ksRoll', 'ksTaxes', 'ksLostPct', 'ksGross', 'ksWithheld', 'ksCheck', 'ksFed', 'ksAddl', 'ksStateTax',
                 'ksSettle', 'ksTrapCheck', 'ksTrapMakeUp', 'ksTrapTax', 'ksTrapCredit'];

  function update() {
    var mode = el('ksTaxMode').value;
    el('ksBracketFields').classList.toggle('form-field-hidden', mode !== 'brackets');
    el('ksRateField').classList.toggle('form-field-hidden', mode !== 'rate');
    var p = {
      balance: num('ksBalance'), age: num('ksAge'), retire: num('ksRetire'), sepAge: Math.round(num('ksSepAge')),
      safety: el('ksSafety').checked, rate: num('ksReturn') / 100, planFee: num('ksPlanFee') / 100,
      iraFee: num('ksIraFee') / 100, state: num('ksState') / 100, retireTax: num('ksRetireTax') / 100,
      tax: { mode: mode, rate: num('ksFedRate') / 100, status: el('ksStatus').value, income: num('ksIncome') }
    };
    var error = el('ksError'), msg = '';
    var needed = [p.balance, p.age, p.retire, p.sepAge, p.rate, p.planFee, p.iraFee, p.state, p.retireTax,
                  mode === 'rate' ? p.tax.rate : p.tax.income];
    if (needed.some(isNaN)) msg = 'Fill in every field with a number.';
    else if (p.balance < 0) msg = 'Enter a balance of 0 or more.';
    else if (p.age < 18 || p.age > 80 || p.retire > 90 || p.retire < p.age) msg = 'Enter an age from 18 to 80 and a retirement age from your age up to 90.';
    else if (p.sepAge < 18 || p.sepAge > Math.floor(p.age) + 1) msg = 'The age you turn in the year you left can’t be more than a year above your age now.';
    else if (p.rate < -0.2 || p.rate > 0.2 || p.planFee < 0 || p.planFee > 0.05 || p.iraFee < 0 || p.iraFee > 0.05) msg = 'Use a return from -20% to 20% and fees from 0% to 5%.';
    else if (p.state < 0 || p.state > 0.15 || p.retireTax < 0 || p.retireTax > 0.6) msg = 'Use a state rate from 0% to 15% and a retirement tax rate from 0% to 60%.';
    else if (mode === 'rate' ? (p.tax.rate < 0 || p.tax.rate > 0.37) : p.tax.income < 0) msg = mode === 'rate' ? 'Use a federal rate from 0% to 37%.' : 'Enter other income of 0 or more.';
    error.hidden = !msg;
    if (msg) {
      error.textContent = msg;
      OUTPUTS.forEach(function (id) { set(id, '–'); });
      set('ksNote', ''); set('ksTrapNote', '');
      fillRows('ksCompare', []); fillRows('ksSchedule', []);
      return;
    }
    var r = compute(p);
    var retireLabel = ageText(p.retire);
    set('ksRollLabel', 'Rolled over, at age ' + retireLabel);
    set('ksNet', money(r.net));
    set('ksRoll', money(r.ira));
    set('ksTaxes', money(r.totalTax));
    set('ksLostPct', p.balance > 0 ? (r.totalTax / p.balance * 100).toFixed(1) + '%' : '0.0%');
    set('ksGross', money(p.balance));
    set('ksWithheld', money(r.withheld));
    set('ksCheck', money(r.check));
    set('ksFedLabel', 'Federal income tax (' + (p.balance > 0 ? (r.fed / p.balance * 100).toFixed(1) : '0.0') + '% of it, ' + TAX_YEAR + ')');
    set('ksFed', money(r.fed));
    set('ksAddl', r.early ? money(r.addl) : 'None');
    set('ksStateTax', money(r.state));
    set('ksSettleLabel', r.settle >= 0 ? 'Federal tax still owed at filing' : 'Federal refund of over-withholding');
    set('ksSettle', money(Math.abs(r.settle)));

    var why;
    if (p.age >= EARLY_AGE) why = 'You are 59½ or older, so there is no 10% additional tax.';
    else if (!r.early) why = 'You left this employer in or after the year you turned ' + (p.safety ? SEPARATION_AGE_SAFETY : SEPARATION_AGE) +
      ', so payouts from this plan avoid the 10% additional tax even before 59½.';
    else why = 'You are under 59½ and left before the year you turned ' + (p.safety ? SEPARATION_AGE_SAFETY : SEPARATION_AGE) +
      ', so a cash-out also owes the 10% additional tax.';
    set('ksNote', why + ' Cashing out keeps ' + money(r.net) + ' today; rolling it over could grow to ' + money(r.ira) +
        ' by age ' + retireLabel + ' (' + money(r.iraAfter) + ' after tax).');

    fillRows('ksCompare', [
      ['Cash out', money(r.totalTax), money(r.net), '–', '–'],
      ['Direct rollover to an IRA', money(0), money(0), money(r.ira), money(r.iraAfter)],
      ['Leave it in the plan', money(0), money(0), money(r.plan), money(r.planAfter)]
    ]);
    set('ksColValue', 'Value at age ' + retireLabel);

    set('ksTrapCheck', money(r.check));
    set('ksTrapMakeUp', money(r.trapMakeUp));
    set('ksTrapTax', money(r.trapTax));
    set('ksTrapCredit', money(r.withheld));
    set('ksTrapNote', 'Deposit ' + money(p.balance) + ' within 60 days, the ' + money(r.check) + ' check plus ' + money(r.trapMakeUp) +
        ' of your own money, and none of it is taxed; the ' + money(r.withheld) + ' withheld comes back when you file. Deposit only the check and the ' +
        money(r.trapMakeUp) + ' becomes taxable income' + (r.early ? ' with the 10% additional tax' : '') +
        '. Miss the 60 days entirely and it is taxed like a full cash-out.');

    fillRows('ksSchedule', r.rows.map(function (row) { return [ageText(row.age), money(row.ira), money(row.plan)]; }));
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('ksForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
